func TestWhatEachPlatformEngineCannotSayIsNotInItsCeiling(emonT *testing.T) {
	port.AssertEq(emonT, engines.PkEngineCaps(engines.EngAppleVision()), 1056992, "Vision: quad angle lconf wlang walts")
	port.AssertEq(emonT, engines.PkEngineOen(engines.EngAppleVision()), 3, "answers as engine 3")
	port.AssertEq(emonT, engines.PkEngineNeeds(engines.EngAppleVision()), 0, "needs no pack")
	port.AssertEq(emonT, engines.PkEngineCaps(engines.EngAppleVision()), visionCaps(), "the bits, named")
	port.AssertEq(emonT, oil.OilNativeCheck(engines.PkEngineCaps(engines.EngAppleVision()), oil.OcWconf()), 0, "no word confidence in the ceiling")
	port.AssertEq(emonT, engines.PkEngineCaps(engines.EngWindowsMediaOcr()), 9216, "Windows: deskew wlang")
	port.AssertEq(emonT, engines.PkEngineNeeds(engines.EngWindowsMediaOcr()), 0, "needs no pack")
	port.AssertEq(emonT, engines.PkEngineOen(engines.EngWindowsMediaOcr()), 5, "answers as engine 5")
}

func TestNoEngineWithoutAConfidenceIsEverCalibrated(emonT *testing.T) {
	port.AssertEq(emonT, ocalib.OcalWord(oil.OenWindowsMediaOcr(), 0, 500), -1, "Windows.Media.Ocr has no map: ruling 3, uncalibrated for good")
	port.AssertEq(emonT, ocalib.OcalWord(oil.OenWindowsMediaOcr(), 0, -1), -1, "no raw value")
	port.AssertEq(emonT, ocalib.OcalOrPrior(ocalib.OcalWord(oil.OenWindowsMediaOcr(), 0, 500), 500), 500, "ranking and voting may use the prior, nothing else may")
}
